-- CR1 — Seed the owner-managed public pages with the approved D1/D1.5 copy.
--
-- The wording, ordering and structure below were carried over verbatim from
-- the previously code-owned public routes so the public appearance is
-- stable after migration. Every page is published as revision 1 with no
-- actor (no staff exists at migration time). Tokens such as
-- {{services.count_words}} are resolved by the renderer from the live
-- domains so counts never become false when the owner adds content.

insert into public.website_section_types (key, display_name, scope, system_module) values
  ('team_credentials', 'Team and credentials (system)', 'system', true),
  ('intake_success', 'Intake confirmation (system)', 'system', true)
on conflict (key) do update set display_name = excluded.display_name, scope = excluded.scope, system_module = excluded.system_module, enabled = true;

create or replace function private.seed_website_page(
  target_key text, target_type text, target_path text, target_title text,
  target_seo_title text, target_seo_description text, target_noindex boolean, target_sections jsonb
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  new_id uuid;
  section jsonb;
  index integer := 0;
  snapshot jsonb;
  revision_id uuid;
begin
  if exists (select 1 from public.website_pages where page_key = target_key) then
    return;
  end if;
  insert into public.website_pages (page_key, page_type, path, title, status, seo_title, seo_description, noindex)
  values (target_key, target_type, target_path, target_title, 'draft', target_seo_title, target_seo_description, target_noindex)
  returning id into new_id;
  for section in select value from jsonb_array_elements(target_sections) loop
    insert into public.website_page_sections (page_id, section_type, variant, tone, spacing, locked, label, config, sort_order)
    values (new_id, section ->> 'type', coalesce(section ->> 'variant', 'default'), coalesce(section ->> 'tone', 'paper'),
            coalesce(section ->> 'spacing', 'standard'), coalesce((section ->> 'locked')::boolean, false), section ->> 'label',
            coalesce(section -> 'config', '{}'::jsonb), index);
    index := index + 1;
  end loop;
  snapshot := private.website_page_snapshot(new_id);
  insert into public.website_page_revisions (page_id, revision_no, kind, summary, snapshot, media_ids)
  values (new_id, 1, 'published', 'Initial content carried over from the approved D1 build', snapshot, private.website_snapshot_media_ids(snapshot))
  returning id into revision_id;
  update public.website_pages set status = 'published', published_revision_id = revision_id, published_at = now(), version = version + 1 where id = new_id;
end;
$$;

