select private.seed_website_page('contact', 'system', '/contact', 'Contact', 'Contact', 'Reach RENZ by email or WhatsApp, send the contact form, or start a project brief.', false, '[{"type": "masthead", "tone": "paper", "variant": "default", "spacing": "standard", "locked": true, "label": "Masthead", "config": {"eyebrow": "Contact", "title": "Begin with the right line.", "summary": "Reach {{business.short_name}} directly by email or WhatsApp, send the short contact form below, or start a project brief and let the details lead the conversation.", "datum_index": "06", "compact": true, "field_variant": "survey", "facts": [{"label": "Email", "value": "{{contact.email}}"}, {"label": "WhatsApp", "value": "Messages only"}, {"label": "Reply", "value": "By the channel you choose"}]}}, {"type": "contact_channels", "tone": "paper", "variant": "default", "spacing": "compact", "locked": true, "label": "Contact channels", "config": {"whatsapp_title": "Message {{business.short_name}}", "whatsapp_body": "Fastest for a first question. Messages only — the number does not take calls.", "email_body": "Best for drawings, documents and anything you want on record.", "start_label": "Start a project", "start_title": "{{process.count_words}} guided steps", "start_body": "Need, site, scale, parameters, your details, files, review — about five minutes.", "phone_title": "Call {{business.short_name}}"}}, {"type": "contact_form", "tone": "concrete", "variant": "default", "spacing": "standard", "locked": true, "label": "Contact form", "config": {"kicker": "Contact form", "heading": "Send a short message.", "intro": "A subject, a message and how to reach you. It lands in the RENZ team''s register with a reference number you can quote later.", "reply_label": "How RENZ replies", "reply_steps": ["Your message is registered with a reference number.", "RENZ replies on the channel you chose — WhatsApp or email.", "If it is a project, the next step is a short conversation, not a commitment."], "channels_label": "Direct channels", "whatsapp_note": "Messages only", "email_note": "Drawings, documents, anything on record", "hours_label": "Hours", "area_label": "Works across", "follow_label": "Follow", "paused_text": "Online enquiries are paused at the moment. Email or WhatsApp reach {{business.short_name}} directly.", "aside_prefix": "Looking for a specific service?", "aside_service_label": "Send a service enquiry", "aside_middle": "Need materials?", "aside_material_label": "Send a material enquiry"}}, {"type": "faq", "tone": "paper", "variant": "default", "spacing": "standard", "locked": false, "label": "Common questions", "config": {"kicker": "Before you write", "heading": "Common questions.", "intro": null, "items": [{"question": "What should I prepare before I get in touch?", "answer": "The location (or a description of the land), what you want to build, the budget band you are working to, and any drawings, sketches or photographs you already have. None of it needs to be final."}, {"question": "Do I need to know which service I need?", "answer": "No. Describe the situation and RENZ replies with the service that fits — design, execution, a hybrid, supervision or a consultation — and what it would deliver."}, {"question": "Can RENZ work with my existing contractor?", "answer": "Yes. Supervision is an independent engagement: site checkpoints, material verification and a decision log while another contractor builds."}, {"question": "How does RENZ reply?", "answer": "By WhatsApp message or email, whichever you chose on the form. RENZ does not cold-call; the public WhatsApp number is for messages, not calls."}]}}]'::jsonb);

select private.seed_website_page('start-a-project', 'system', '/start-a-project', 'Start a Project', 'Start a Project', 'Tell RENZ what you need in seven short steps. Your brief lands directly with the team.', false, '[{"type": "masthead", "tone": "paper", "variant": "default", "spacing": "standard", "locked": true, "label": "Masthead", "config": {"eyebrow": "Start a Project", "title": "Start with a clear brief.", "summary": "{{process.count_words}} short steps. No account, no jargon: describe what you need and RENZ takes it from there.", "datum_index": "07", "compact": false, "field_variant": "drawing", "facts": []}}, {"type": "start_project_wizard", "tone": "paper", "variant": "default", "spacing": "standard", "locked": true, "label": "Start a Project wizard", "config": {"next_steps": ["Your brief reaches the RENZ team with a reference number you can quote.", "RENZ replies by email or WhatsApp to confirm scope and arrange a first conversation.", "You receive a written summary of the brief and the service that fits it."], "paused_text": "Online intake is paused at the moment. Email or WhatsApp reach {{business.short_name}} directly."}}]'::jsonb);

select private.seed_website_page('start-a-project-success', 'system', '/start-a-project/success', 'Brief received', 'Brief received', 'Your project brief has reached RENZ.', true, '[{"type": "masthead", "tone": "paper", "variant": "default", "spacing": "standard", "locked": true, "label": "Masthead", "config": {"eyebrow": "Start a Project", "title": "Brief received.", "summary": "Your brief is now with the RENZ team.", "datum_index": "07", "compact": false, "field_variant": "drawing", "facts": []}}, {"type": "intake_success", "tone": "paper", "variant": "default", "spacing": "standard", "locked": true, "label": "Confirmation", "config": {"heading": "Thank you. Your project brief is with RENZ.", "next_steps": "Keep this reference. {{business.short_name}} reviews every brief by hand and replies through the contact details you gave; there is no automated reply.", "invalid_text": "This page needs a valid reference.", "restart_label": "Start a new brief"}}]'::jsonb);

